param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'nullable-primitive-generic-construction-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}


function Shape($name){$definition=[object].Assembly.GetType('System.Nullable`1');switch($name){'D'{return $definition};'C'{return $definition.MakeGenericType([type[]]@([int]))};'P'{return $definition.GetGenericArguments()[0]};'ListP'{return ([object].Assembly.GetType('System.Collections.Generic.List`1')).GetGenericArguments()[0]};default{if($name.StartsWith('System.')){return [Type]::GetType($name,$true,$false)};return [Type]::GetType('System.'+$name,$true,$false)}}}
function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$definition=Shape 'D';$method=[Type].GetMethod('MakeGenericType',[type[]]@([type[]]));$nullInputControls=0
foreach($spec in $plan.cases){$arguments=$null;$saved=$null;if($null -ne $spec.arguments){$arguments=[type[]]::new($spec.arguments.Count);for($i=0;$i -lt $arguments.Length;$i++){if($null -ne $spec.arguments[$i]){$arguments[$i]=Shape $spec.arguments[$i]}else{if($null -ne $arguments[$i]){throw 'Null element coerced'};$nullInputControls++}};$saved=$arguments.Clone()}else{$nullInputControls++};$invokeArgs=[object[]]::new(1);$invokeArgs[0]=$arguments;$row=[ordered]@{key=$spec.key;outcome='error';exception=$null;messageUnits=$null;hResult=0;paramUnits=$null;fullName=$null;assemblyQualifiedName=$null;name=$null;namespace=$null;isValueType=$null;containsGenericParameters=$null;isGenericTypeDefinition=$null;genericDefinition=$null;argumentName=$null;canonicalRepeat=$null;defensiveCopy=$null;inputUnchanged=$true;fullRoundtrip=$null}
try{$type=$method.Invoke($definition,$invokeArgs);$row.outcome='type';$row.fullName=$type.FullName;$row.assemblyQualifiedName=$type.AssemblyQualifiedName;$row.name=$type.Name;$row.namespace=$type.Namespace;$row.isValueType=$type.IsValueType;$row.containsGenericParameters=$type.ContainsGenericParameters;$row.isGenericTypeDefinition=$type.IsGenericTypeDefinition;$row.genericDefinition=$type.GetGenericTypeDefinition().FullName;$row.argumentName=$type.GetGenericArguments()[0].Name;$row.canonicalRepeat=[object]::ReferenceEquals($type,$method.Invoke($definition,$invokeArgs));$copy=$type.GetGenericArguments();$first=$copy[0];$copy[0]=$null;$row.defensiveCopy=[object]::ReferenceEquals($first,$type.GetGenericArguments()[0]);if($null -ne $type.FullName){$row.fullRoundtrip=[object]::ReferenceEquals($type,[Type]::GetType($type.FullName,$true,$false))}}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};if($errorValue -isnot [ArgumentException]){throw};$row.exception=$errorValue.GetType().FullName;$row.messageUnits=Units $errorValue.Message;$row.hResult=$errorValue.HResult;$row.paramUnits=Units $errorValue.ParamName};if($null -ne $arguments){for($i=0;$i -lt $arguments.Length;$i++){if(-not [object]::ReferenceEquals($arguments[$i],$saved[$i])){$row.inputUnchanged=$false}}};$rows.Add($row)}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();nullInputControls=$nullInputControls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS nullable construction: $($rows.Count) cases"
